lemma ev_apply {D : (Λ →₀ M) →ₗ[K] (Λ →₀ M)}
    (hD : IsEquivariant (translation (K := K)) (translation (K := K)) D)
    (χ : AddChar Λ K) (ψ : Λ →₀ M) : ev χ (D ψ) = symbol χ D (ev χ ψ)

lemma symbol_comp {D₁ D₂ : (Λ →₀ M) →ₗ[K] (Λ →₀ M)}
    (h₁ : IsEquivariant (translation (K := K)) (translation (K := K)) D₁)
    (χ : AddChar Λ K) : symbol χ (D₁ ∘ₗ D₂) = symbol χ D₁ ∘ₗ symbol χ D₂

lemma conj_of_covariant {b : BrillouinZone G → Matrix F F ℂ} {s : CellSymmetry G F}
    (hb : IsCovariant b s) (χ : BrillouinZone G) :
    b (s • χ) = fibreMatrix s (s • χ) * b χ * (fibreMatrix s (s • χ))ᴴ

lemma charpoly_eq_of_covariant {b : BrillouinZone G → Matrix F F ℂ} {s : CellSymmetry G F}
    (hb : IsCovariant b s) (χ : BrillouinZone G) :
    (b (s • χ)).charpoly = (b χ).charpoly

lemma eigenvalues_eq_of_covariant {b : BrillouinZone G → Matrix F F ℂ}
    (hH : ∀ χ, (b χ).IsHermitian) {s : CellSymmetry G F} (hb : IsCovariant b s)
    (χ : BrillouinZone G) : (hH (s • χ)).eigenvalues = (hH χ).eigenvalues

noncomputable def bandsOnZone {g : PeriodicGraph (Crystal.ofUnitCell G F)}
    {b : BrillouinZone G → Matrix F F ℂ} (hH : ∀ χ, (b χ).IsHermitian)
    (hb : ∀ s : g.symmetries, IsCovariant b s) : g.IrreducibleZone → (F → ℝ)

lemma commute_of_smul_eq {b : BrillouinZone G → Matrix F F ℂ} {s : CellSymmetry G F}
    (hb : IsCovariant b s) {χ : BrillouinZone G} (hχ : s • χ = χ) :
    fibreMatrix s χ * b χ = b χ * fibreMatrix s χ

lemma spectrum_eq_of_covariant {b : BrillouinZone G → Matrix F F ℂ}
    (hH : ∀ χ, (b χ).IsHermitian) {s : CellSymmetry G F} (hb : IsCovariant b s)
    (χ : BrillouinZone G) : spectrum ℂ (b (s • χ)) = spectrum ℂ (b χ)

lemma iUnion_spectrum_eq_of_covers {g : PeriodicGraph (Crystal.ofUnitCell G F)}
    {b : BrillouinZone G → Matrix F F ℂ} (hH : ∀ χ, (b χ).IsHermitian)
    (hb : ∀ s : g.symmetries, IsCovariant b s) {D : Set (BrillouinZone G)}
    (hD : CoversOrbits g D) :
    (⋃ χ : BrillouinZone G, spectrum ℂ (b χ)) = ⋃ χ ∈ D, spectrum ℂ (b χ)

lemma projection_localized_ne_zero {U : Set (PontryaginDual (Multiplicative G))}
    (hU : IsOpen U) (hne : U.Nonempty) {e : EuclideanSpace ℂ (Fin N)} (he : e ≠ 0) :
    UnitaryRep.projection (translation G N) U (localized e) ≠ 0

lemma brillouinZone_ext {χ ψ : BrillouinZone (Fin d → ℤ)}
    (h : ∀ j, χ (Multiplicative.ofAdd (Pi.single j 1)) = ψ (Multiplicative.ofAdd (Pi.single j 1))) :
    χ = ψ

lemma hypercubic_bond_length (d : ℕ) {x y : (hypercubic d).Site}
    (h : (hypercubicGraph d).toSimpleGraph.Adj x y) :
    (hypercubicGeometry d).distance x y = 1

lemma fcc_bond_length {a : ℝ} (ha : 0 < a) {x y : fcc.Site}
    (h : fccGraph.toSimpleGraph.Adj x y) :
    (fccGeometry a a a ha ha ha).distance x y = a * Real.sqrt 2 / 2

lemma bcc_bond_length {a : ℝ} (ha : 0 < a) {x y : bcc.Site}
    (h : bccGraph.toSimpleGraph.Adj x y) :
    (bccGeometry a a a ha ha ha).distance x y = a * Real.sqrt 3 / 2

lemma linear_mem_bondDifferences {bonds : List (Bond G F)} {s : CellSymmetry G F}
    (hs : s ∈ (ofBonds bonds).symmetries) {e : G} (he : e ∈ bondDifferences bonds) :
    s.linear e ∈ bondDifferences bonds

lemma linear_mem_bondDifferences_iff {bonds : List (Bond G F)} {s : CellSymmetry G F}
    (hs : s ∈ (ofBonds bonds).symmetries) (e : G) :
    s.linear e ∈ bondDifferences bonds ↔ e ∈ bondDifferences bonds

lemma sum_region {M : Type*} [AddCommMonoid M] {B : Finset (Fin d → ℤ)}
    (f : (Crystal.ofUnitCell (Fin d → ℤ) F).Site → M) :
    ∑ x ∈ region B, f x = ∑ c ∈ B, ∑ i : F, f ⟨c, i⟩

lemma Interaction.hamiltonian_smul (I : Interaction (fun _ : S => Ω₀)) {γ : Γ}
    (hI : I.IsInvariant γ) (Λ : Finset S) :
    quantumIso γ Λ (I.hamiltonian Λ) = I.hamiltonian (γ • Λ)

lemma Interaction.canonicalState_smul (I : Interaction (fun _ : S => Ω₀)) {γ : Γ}
    (hI : I.IsInvariant γ) (β : ℝ) (Λ : Finset S) (a : Alg (fun _ : S => Ω₀) Λ) :
    I.canonicalState β (γ • Λ) (quantumIso γ Λ a) = I.canonicalState β Λ a

def invariantLimit (φ : AlgState (uniformNet (S := S) Ω₀).Quasilocal) (F : ι → Finset Γ)
    (hne : ∀ i, (F i).Nonempty) (𝒰 : Ultrafilter ι) :
    AlgState (uniformNet (S := S) Ω₀).Quasilocal

def Interaction.grandCanonicalLimitState (I : Interaction Ω) (q : Charge Ω) (β μ : ℝ)
    (𝒰 : Ultrafilter (Finset S)) (h𝒰 : (𝒰 : Filter (Finset S)) ≤ atTop) :
    AlgState (quantumNet Ω).Quasilocal

lemma meanOf_timeReversal {A : T.HilbertSpace →ₗ[ℂ] T.HilbertSpace}
    (hA : ∀ ψ, A (T.timeReversal ψ) = T.timeReversal (A ψ)) (ψ : T.HilbertSpace) :
    T.meanOf A (T.timeReversal ψ) = T.meanOf A ψ

lemma flucOf_timeReversal {A : T.HilbertSpace →ₗ[ℂ] T.HilbertSpace}
    (hA : ∀ ψ, A (T.timeReversal ψ) = T.timeReversal (A ψ)) (ψ : T.HilbertSpace) :
    T.flucOf A (T.timeReversal ψ) = T.timeReversal (T.flucOf A ψ)
